def test_run_bench_calls_registered_function_and_updates_state(monkeypatch):
    captured = {}

    def fake_bench(**kwargs):
        captured.update(kwargs)
        return {"age": [1, 2], "sex": [0, 1]}, [0, 1], [0.2, 0.8]

    monkeypatch.setitem(
        m.BENCH_REGISTRY,
        "test.bench",
        {
            "label": "Test",
            "params": {
                "test_size": {
                    "type": "train_percent",
                    "default": 50,
                }
            },
            "func": fake_bench,
        },
    )

    # Dirty downstream state first; run_bench should clear it.
    m.STATE["sensitive"] = object()
    m.STATE["report"] = object()
    m.STATE["html"] = "old html"

    result = m.run_bench(
        {
            "bench": "test.bench",
            "params": {"test_size": 80},
        }
    )

    assert captured == {"test_size": 0.2}
    assert m.STATE["x"] == {"age": [1, 2], "sex": [0, 1]}
    assert m.STATE["y"] == [0, 1]
    assert m.STATE["yhat"] == [0.2, 0.8]
    assert m.STATE["sensitive"] is None
    assert m.STATE["report"] is None
    assert m.STATE["html"] is None

    assert result == {
        "summary": {
            "x_keys": 2,
            "len_y": 2,
            "len_yhat": 2,
        },
        "details": {
            "bench": "test.bench",
            "params": {"test_size": 0.2},
            "x_key_list": ["age", "sex"],
        },
    }


