class FakeTyped:
    def __init__(self, threshold):
        self.threshold = threshold

    def __matmul__(self, values):
        return ("typed", self.threshold, values)


class FakeSensitive:
    def __init__(self, *dims):
        self.dims = dims
        self.intersectional_min_size = None
        self.was_strict = False

    def intersectional(self, min_size=0):
        self.intersectional_min_size = min_size
        return self

    def strict(self):
        self.was_strict = True
        return self

    def branches(self):
        return {"g1": object(), "g2": object()}

    def sum(self):
        return 42


