def test_run_report_generates_html_without_filter(monkeypatch):
    m.STATE.update(
        y=[0, 1],
        yhat=[0.1, 0.9],
        sensitive="sensitive-object",
    )

    fake_report = FakeReport()
    captured = {}

    def pairwise(**kwargs):
        captured.update(kwargs)
        return fake_report

    class FakeReports:
        pass

    fake_reports = FakeReports()
    fake_reports.pairwise = pairwise
    monkeypatch.setattr(m.fb, "reports", fake_reports)

    fake_env = object()
    monkeypatch.setitem(
        m.VIS_REGISTRY,
        "test-vis",
        {"label": "test", "env": lambda: fake_env},
    )

    result = m.run_report(
        {
            "report": "pairwise",
            "visualization": "test-vis",
            "depth": 2,
        }
    )

    assert captured == {
        "predictions": [0.1, 0.9],
        "labels": [0, 1],
        "sensitive": "sensitive-object",
    }
    assert m.STATE["report"] is fake_report
    assert m.STATE["html"] == "<html>report</html>"
    assert fake_report.show_args == {"env": fake_env, "depth": 2}
    assert result["summary"] == {
        "report": "pairwise",
        "filter": "none",
        "visualization": "test-vis",
        "depth": 2,
    }


