def test_http_route_exception_becomes_400(monkeypatch, http_server):
    def boom(_body):
        raise ValueError("bad request")

    monkeypatch.setitem(m.ROUTES_POST, "/api/test-error", boom)

    status, payload = request_json(
        f"{http_server}/api/test-error",
        method="POST",
        body={},
    )

    assert status == 400
    assert payload["error"] == "bad request"
    assert "ValueError: bad request" in payload["traceback"]
